<?php
declare(strict_types=1);
$config = require __DIR__.'/../config/config.php';
date_default_timezone_set($config['timezone'] ?? 'Africa/Lagos');
if (session_status() !== PHP_SESSION_ACTIVE) { session_name($config['session_name'] ?? 'NACOS_VOTE_SESSION'); session_set_cookie_params(['httponly'=>true,'secure'=>isset($_SERVER['HTTPS']),'samesite'=>'Lax']); session_start(); }
function db(): PDO { static $pdo=null; global $config; if(!$pdo){$d=$config['db'];$pdo=new PDO("mysql:host={$d['host']};dbname={$d['name']};charset={$d['charset']}",$d['user'],$d['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);} return $pdo; }
function e(?string $v): string { return htmlspecialchars($v ?? '',ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function redirect(string $to): never { header('Location: '.$to); exit; }
function csrf_token(): string { if(empty($_SESSION['_csrf'])) $_SESSION['_csrf']=bin2hex(random_bytes(32)); return $_SESSION['_csrf']; }
function csrf_check(): void { if($_SERVER['REQUEST_METHOD']==='POST' && !hash_equals($_SESSION['_csrf']??'',$_POST['_csrf']??'')){http_response_code(419);exit('Security token expired. Go back and try again.');} }
function user(): ?array { return $_SESSION['user']??null; }
function require_login(): void { if(!user()) redirect('index.php?page=login'); }
function require_role(array $roles): void { require_login(); if(!in_array(user()['role'],$roles,true)){http_response_code(403);exit('You are not authorized to access this page.');} }
function audit(string $action,string $details=''): void { try{$s=db()->prepare('INSERT INTO audit_logs(user_id,action,details,ip_address) VALUES(?,?,?,?)');$s->execute([user()['id']??null,$action,$details,$_SERVER['REMOTE_ADDR']??null]);}catch(Throwable $x){} }
function flash(string $type,string $msg): void { $_SESSION['flash']=['type'=>$type,'msg'=>$msg]; }
function render_header(string $title): void { $u=user(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($title)?> · NACOS E-Voting</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="public/assets/style.css" rel="stylesheet"></head><body><nav class="navbar navbar-expand-lg navbar-dark topbar"><div class="container"><a class="navbar-brand fw-bold" href="index.php"><span class="brand-mark">N</span> NACOS <span class="fw-normal opacity-75">E-Voting</span></a><button class="navbar-toggler" data-bs-toggle="collapse" data-bs-target="#nav"><span class="navbar-toggler-icon"></span></button><div class="collapse navbar-collapse" id="nav"><div class="navbar-nav ms-auto align-items-lg-center gap-lg-2"><?php if($u): ?><a class="nav-link" href="index.php?page=dashboard">Dashboard</a><?php if($u['role']==='student'): ?><a class="nav-link" href="index.php?page=elections">Elections</a><a class="nav-link" href="index.php?page=candidate-applications">Candidate applications</a><?php endif; ?><?php if(in_array($u['role'],['admin','officer'],true)): ?><a class="nav-link" href="index.php?page=manage">Manage</a><a class="nav-link" href="index.php?page=reports">Reports</a><?php if($u['role']==='admin'): ?><a class="nav-link" href="index.php?page=candidate-review">Candidate review</a><?php endif; ?><?php endif; ?><span class="nav-link small opacity-75"><?=e($u['full_name'])?></span><a class="btn btn-sm btn-light" href="index.php?page=logout">Sign out</a><?php else: ?><a class="nav-link" href="index.php?page=login">Sign in</a><a class="btn btn-sm btn-light" href="index.php?page=register">Student registration</a><?php endif; ?></div></div></div></nav><main class="container py-4 py-lg-5"><?php if(!empty($_SESSION['flash'])){$f=$_SESSION['flash'];unset($_SESSION['flash']);?><div class="alert alert-<?=e($f['type'])?> alert-dismissible fade show" role="alert"><?=e($f['msg'])?><button class="btn-close" data-bs-dismiss="alert"></button></div><?php } ?>
<?php }
function render_footer(): void { ?></main><footer class="footer py-4"><div class="container d-flex flex-wrap justify-content-between gap-2"><span>© <?=date('Y')?> NACOS · Secure digital elections</span><span>Built for transparent student representation</span></div></footer><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="public/assets/app.js"></script></body></html><?php }
csrf_check();
